var pgStatenames = [...]string{}

const pgEofCode = 1
const pgErrCode = 2
const pgInitialStackSize = 16

//line gram.y:17931

// OnConflict action constants
const (
	ONCONFLICT_NONE    = 0
	ONCONFLICT_NOTHING = 1
	ONCONFLICT_UPDATE  = 2
)

// ViewCheckOption constants
const (
	VIEW_CHECK_OPTION_NONE     = 0
	VIEW_CHECK_OPTION_LOCAL    = 1
	VIEW_CHECK_OPTION_CASCADED = 2
)

// Helper functions called from grammar actions

// grammarError records an error a grammar action raises, as an ereport in
// PostgreSQL's gram.y does, with its SQLSTATE, message, hint and 0-based
// position. The action then ends the parse, as ereport's longjmp does, so the
// first error stands.
func grammarError(lex pgLexer, code, message, hint string, loc nodes.ParseLoc) {
	if pl, ok := lex.(*parserLexer); ok && pl.err == nil {
		pl.err = &ParseError{Code: code, Message: message, Hint: hint, Position: int(loc)}
	}
}

// checkConstraintAttrConflict raises PostgreSQL 16's error for constraint
// attributes that contradict each other once the one at loc is added to bits.
func checkConstraintAttrConflict(lex pgLexer, bits int64, loc nodes.ParseLoc) bool {
	has := func(a, b int64) bool { return bits&a != 0 && bits&b != 0 }
	switch {
	case has(nodes.CAS_NOT_DEFERRABLE, nodes.CAS_INITIALLY_DEFERRED):
		grammarError(lex, codeSyntaxError, "constraint declared INITIALLY DEFERRED must be DEFERRABLE", "", loc)
	case has(nodes.CAS_NOT_DEFERRABLE, nodes.CAS_DEFERRABLE), has(nodes.CAS_INITIALLY_IMMEDIATE, nodes.CAS_INITIALLY_DEFERRED):
		grammarError(lex, codeSyntaxError, "conflicting constraint properties", "", loc)
	default:
		return true
	}
	return false
}

// checkConstraintAttrs raises PostgreSQL 16's processCASbits error for an
// attribute a constraint of the kind cannot take: deferrable is whether it
// may be DEFERRABLE or INITIALLY DEFERRED, notValid NOT VALID and noInherit
// NO INHERIT.
func checkConstraintAttrs(lex pgLexer, bits int64, kind string, deferrable, notValid, noInherit bool) bool {
	var marked string
	switch {
	case !deferrable && bits&int64(nodes.CAS_DEFERRABLE|nodes.CAS_INITIALLY_DEFERRED) != 0:
		marked = "DEFERRABLE"
	case !notValid && bits&int64(nodes.CAS_NOT_VALID) != 0:
		marked = "NOT VALID"
	case !noInherit && bits&int64(nodes.CAS_NO_INHERIT) != 0:
		marked = "NO INHERIT"
	default:
		return true
	}
	grammarError(lex, "0A000", kind+" constraints cannot be marked "+marked, "", -1)
	return false
}

// roleIdRefusal is PostgreSQL 16's 42939 message for a role specifier that
// cannot name a role, as RoleId refuses it, or "" for a name.
func roleIdRefusal(roletype int) string {
	switch nodes.RoleSpecType(roletype) {
	case nodes.ROLESPEC_PUBLIC:
		return "role name \"public\" is reserved"
	case nodes.ROLESPEC_CURRENT_ROLE:
		return "CURRENT_ROLE cannot be used as a role name here"
	case nodes.ROLESPEC_CURRENT_USER:
		return "CURRENT_USER cannot be used as a role name here"
	case nodes.ROLESPEC_SESSION_USER:
		return "SESSION_USER cannot be used as a role name here"
	}
	return ""
}

// grammarSyntaxError raises a grammar action's parser_yyerror(message), as
// PostgreSQL 16's does: 42601, message at or near the token the lexer
// returned last, at that token. The first error stands.
func grammarSyntaxError(lex pgLexer, message string) {
	if pl, ok := lex.(*parserLexer); ok && pl.err == nil {
		pl.err = &ParseError{Code: codeSyntaxError, Message: pl.atOrNear(message), Position: pl.lastLoc}
	}
}

// setParseResult stores the parse result in the lexer.
func setParseResult(lex pgLexer, result *nodes.List) {
	if pl, ok := lex.(*parserLexer); ok {
		pl.result = result
	}
}

func makeList(n nodes.Node) *nodes.List {
	if n == nil {
		return &nodes.List{}
	}
	return &nodes.List{Items: []nodes.Node{n}}
}

func appendList(l *nodes.List, n nodes.Node) *nodes.List {
	if l == nil {
		return makeList(n)
	}
	if n != nil {
		l.Items = append(l.Items, n)
	}
	return l
}

func prependList(n nodes.Node, l *nodes.List) *nodes.List {
	if l == nil {
		return makeList(n)
	}
	if n != nil {
		l.Items = append([]nodes.Node{n}, l.Items...)
	}
	return l
}

func makeList2(a nodes.Node, b nodes.Node) *nodes.List {
	return &nodes.List{Items: []nodes.Node{a, b}}
}

func makeListNode(l *nodes.List) nodes.Node {
	return l
}

func makeRangeVar(names *nodes.List, location nodes.ParseLoc) nodes.Node {
	rv := &nodes.RangeVar{Inh: true, Relpersistence: 'p', Location: location}
	if names != nil && len(names.Items) > 0 {
		switch len(names.Items) {
		case 1:
			rv.Relname = names.Items[0].(*nodes.String).Str
		case 2:
			rv.Schemaname = names.Items[0].(*nodes.String).Str
			rv.Relname = names.Items[1].(*nodes.String).Str
		case 3:
			rv.Catalogname = names.Items[0].(*nodes.String).Str
			rv.Schemaname = names.Items[1].(*nodes.String).Str
			rv.Relname = names.Items[2].(*nodes.String).Str
		}
	}
	return rv
}

func makeAExpr(kind nodes.A_Expr_Kind, op string, lexpr, rexpr nodes.Node, location nodes.ParseLoc) nodes.Node {
	return &nodes.A_Expr{
		Kind:     kind,
		Name:     &nodes.List{Items: []nodes.Node{&nodes.String{Str: op}}},
		Lexpr:    lexpr,
		Rexpr:    rexpr,
		Location: location,
	}
}

// makeAExprFromList creates an A_Expr with an operator name list (from qual_Op).
// makeNameListAsAnyNameList wraps each name string into a single-element
// List (matching PG's any_name format for DropStmt.Objects).
func makeNameListAsAnyNameList(names *nodes.List) *nodes.List {
	if names == nil {
		return nil
	}
	result := &nodes.List{}
	for _, item := range names.Items {
		result.Items = append(result.Items, &nodes.List{Items: []nodes.Node{item}})
	}
	return result
}

// makeStringConstCast is PostgreSQL's: the constant at location, cast with
// no location of its own.
func makeStringConstCast(s string, location nodes.ParseLoc, typeName *nodes.TypeName) nodes.Node {
	return &nodes.TypeCast{
		Arg:      makeStringConst(s, location),
		TypeName: typeName,
		Location: -1,
	}
}

// parsePartitionStrategy is PostgreSQL 16's: list, range or hash in any ASCII
// case, as its PARTITION_STRATEGY_* code, and false for any other name.
func parsePartitionStrategy(strategy string) (string, bool) {
	switch downcase(strategy) {
	case "list":
		return "l", true
	case "range":
		return "r", true
	case "hash":
		return "h", true
	}
	return "", false
}

func makeAExprFromList(kind nodes.A_Expr_Kind, name *nodes.List, lexpr, rexpr nodes.Node, location nodes.ParseLoc) nodes.Node {
	return &nodes.A_Expr{
		Kind:     kind,
		Name:     name,
		Lexpr:    lexpr,
		Rexpr:    rexpr,
		Location: location,
	}
}

// makeAndExpr and makeOrExpr build a connective at the operator's location.
// When the left operand is already the same connective its argument list is
// extended instead, so a chain arrives as one BoolExpr however long it is,
// as in PostgreSQL 16: "a AND b AND c" and "(a AND b) AND c" are one AND of
// three, while "a AND (b AND c)" keeps its inner AND, since only the left
// operand is inspected. The extended node keeps its first operator's
// location.
func makeAndExpr(lexpr, rexpr nodes.Node, location nodes.ParseLoc) *nodes.BoolExpr {
	return makeConnective(nodes.AND_EXPR, lexpr, rexpr, location)
}

func makeOrExpr(lexpr, rexpr nodes.Node, location nodes.ParseLoc) *nodes.BoolExpr {
	return makeConnective(nodes.OR_EXPR, lexpr, rexpr, location)
}

func makeConnective(boolop nodes.BoolExprType, lexpr, rexpr nodes.Node, location nodes.ParseLoc) *nodes.BoolExpr {
	if be, ok := lexpr.(*nodes.BoolExpr); ok && be.Boolop == boolop && be.Args != nil {
		be.Args.Items = append(be.Args.Items, rexpr)
		return be
	}
	return &nodes.BoolExpr{
		Boolop:   boolop,
		Args:     &nodes.List{Items: []nodes.Node{lexpr, rexpr}},
		Location: location,
	}
}

func makeBetweenArgs(lower, upper nodes.Node) nodes.Node {
	return &nodes.List{Items: []nodes.Node{lower, upper}}
}

// doNegate is PostgreSQL's: a negated numeric constant takes the minus
// sign's location; anything else is a unary minus at location. A Float
// whose negation fits int64 becomes an Integer (int64's least value is
// scanned as a Float, its magnitude being one past int64's greatest), and
// negating that Integer gives the Float back, as int64 cannot hold its
// magnitude.
func doNegate(n nodes.Node, location nodes.ParseLoc) nodes.Node {
	if ac, ok := n.(*nodes.A_Const); ok {
		// PostgreSQL moves any constant to the minus sign, a string
		// included, before it decides whether to fold.
		ac.Location = location
		switch v := ac.Val.(type) {
		case *nodes.Integer:
			if v.Ival == math.MinInt64 {
				ac.Val = &nodes.Float{Fval: strconv.FormatUint(1<<63, 10)}
			} else {
				v.Ival = -v.Ival
			}
			return ac
		case *nodes.Float:
			if i, ok := integerLiteral(v.Fval, true); ok {
				ac.Val = &nodes.Integer{Ival: i}
			} else {
				doNegateFloat(v)
			}
			return ac
		}
	}
	return makeAExpr(nodes.AEXPR_OP, "-", nil, n, location)
}

func concatLists(a, b *nodes.List) *nodes.List {
	if a == nil {
		return b
	}
	if b == nil {
		return a
	}
	result := &nodes.List{Items: make([]nodes.Node, 0, len(a.Items)+len(b.Items))}
	result.Items = append(result.Items, a.Items...)
	result.Items = append(result.Items, b.Items...)
	return result
}

func makeSetOp(op nodes.SetOperation, quantifier int64, larg, rarg nodes.Node) nodes.Node {
	n := &nodes.SelectStmt{
		Op:   op,
		All:  quantifier == SET_QUANTIFIER_ALL,
		Larg: larg.(*nodes.SelectStmt),
		Rarg: rarg.(*nodes.SelectStmt),
	}
	return n
}

func makeTypeName(typeName string) *nodes.TypeName {
	return &nodes.TypeName{
		Names: &nodes.List{Items: []nodes.Node{
			&nodes.String{Str: "pg_catalog"},
			&nodes.String{Str: typeName},
		}},
		Location: -1,
	}
}

func makeIntConst(val int64, location nodes.ParseLoc) nodes.Node {
	return &nodes.A_Const{Val: &nodes.Integer{Ival: val}, Location: location}
}

func makeStringConst(str string, location nodes.ParseLoc) nodes.Node {
	return &nodes.A_Const{Val: &nodes.String{Str: str}, Location: location}
}

func makeBoolAConst(val int64, location nodes.ParseLoc) nodes.Node {
	if val != 0 {
		return &nodes.A_Const{Val: &nodes.String{Str: "t"}, Location: location}
	}
	return &nodes.A_Const{Val: &nodes.String{Str: "f"}, Location: location}
}

func makeNullAConst(location nodes.ParseLoc) nodes.Node {
	return &nodes.A_Const{Isnull: true, Location: location}
}

// makeNotExpr builds NOT at the location PostgreSQL 16 gives it: the NOT
// keyword, or for "x NOT IN (subquery)" and the IS NOT predicates the token
// the grammar names. A NOT is never merged with another.
func makeNotExpr(expr nodes.Node, location nodes.ParseLoc) *nodes.BoolExpr {
	return &nodes.BoolExpr{
		Boolop:   nodes.NOT_EXPR,
		Args:     &nodes.List{Items: []nodes.Node{expr}},
		Location: location,
	}
}

func setFuncAlias(n *nodes.RangeFunction, clause nodes.Node) {
	if clause == nil {
		return
	}
	// If it's an Alias, just set the alias
	if alias, ok := clause.(*nodes.Alias); ok {
		n.Alias = alias
		return
	}
	// If it's a List with [alias, coldeflist], it's a func_alias_clause with column defs
	if list, ok := clause.(*nodes.List); ok && len(list.Items) == 2 {
		if alias, ok2 := list.Items[0].(*nodes.Alias); ok2 {
			n.Alias = alias
		}
		if coldeflist, ok2 := list.Items[1].(*nodes.List); ok2 {
			n.Coldeflist = coldeflist
		}
	}
}

func setJoinQual(n *nodes.JoinExpr, qual nodes.Node) {
	if qual == nil {
		return
	}
	if list, ok := qual.(*nodes.List); ok {
		// Check if this is a USING clause with alias: [nameList, alias]
		if len(list.Items) == 2 {
			if innerList, ok2 := list.Items[0].(*nodes.List); ok2 {
				if alias, ok3 := list.Items[1].(*nodes.Alias); ok3 {
					n.UsingClause = innerList
					n.JoinUsing = alias
					return
				}
			}
		}
		n.UsingClause = list
	} else {
		n.Quals = qual
	}
}

func makeTypeNameFromNameList(names *nodes.List) nodes.Node {
	tn := &nodes.TypeName{Location: -1}
	if names != nil {
		tn.Names = names
	}
	return tn
}

func asJsonOutput(n nodes.Node) *nodes.JsonOutput {
	if n == nil {
		return nil
	}
	return n.(*nodes.JsonOutput)
}

func asJsonBehavior(n nodes.Node) *nodes.JsonBehavior {
	if n == nil {
		return nil
	}
	return n.(*nodes.JsonBehavior)
}

func splitJsonBehaviorClause(n nodes.Node) (*nodes.JsonBehavior, *nodes.JsonBehavior) {
	if n == nil {
		return nil, nil
	}
	list := n.(*nodes.List)
	var onEmpty, onError *nodes.JsonBehavior
	if list.Items[0] != nil {
		onEmpty = list.Items[0].(*nodes.JsonBehavior)
	}
	if list.Items[1] != nil {
		onError = list.Items[1].(*nodes.JsonBehavior)
	}
	return onEmpty, onError
}

func asJsonTablePathSpec(n nodes.Node) *nodes.JsonTablePathSpec {
	if n == nil {
		return nil
	}
	return n.(*nodes.JsonTablePathSpec)
}

func doNegateFloat(f *nodes.Float) {
	if len(f.Fval) > 0 && f.Fval[0] == '-' {
		f.Fval = f.Fval[1:]
	} else {
		f.Fval = "-" + f.Fval
	}
}

func makeDefElem(name string, arg nodes.Node) nodes.Node {
	return &nodes.DefElem{
		Defname:  name,
		Arg:      arg,
		Location: -1,
	}
}

// makeFuncName converts a function name string to a *nodes.List of String nodes.
// With one argument, creates an unqualified name.
// With two arguments, creates a schema-qualified name (e.g. "pg_catalog", "func").
func makeFuncName(parts ...string) *nodes.List {
	items := make([]nodes.Node, len(parts))
	for i, p := range parts {
		items[i] = &nodes.String{Str: p}
	}
	return &nodes.List{Items: items}
}

// makeSQLValueFunction creates a SQLValueFunction node.
func makeSQLValueFunction(op nodes.SVFOp, typmod int, location nodes.ParseLoc) *nodes.SQLValueFunction {
	return &nodes.SQLValueFunction{Op: op, Typmod: int32(typmod), Location: location}
}

// makeTypeCast creates a TypeCast node.
func makeTypeCast(arg nodes.Node, typeName *nodes.TypeName, location nodes.ParseLoc) nodes.Node {
	return &nodes.TypeCast{Arg: arg, TypeName: typeName, Location: location}
}

// roleSpecOrNil safely casts a node to *nodes.RoleSpec, returning nil if the node is nil.
func roleSpecOrNil(n nodes.Node) *nodes.RoleSpec {
	if n == nil {
		return nil
	}
	return n.(*nodes.RoleSpec)
}

// SelectLimit is an internal helper struct for passing LIMIT/OFFSET through grammar rules.
// It is not a Node type - just used during parsing.
type SelectLimit struct {
	LimitOffset nodes.Node
	LimitCount  nodes.Node
	LimitOption nodes.LimitOption
}

// GroupClause is an internal helper struct for passing GROUP BY clause
// distinct flag and list through grammar rules (matches PostgreSQL's GroupClause).
type GroupClause struct {
	Distinct bool
	List     *nodes.List
}

// KeyAction is an internal helper struct for passing FK action and column list
// through grammar rules (matches PostgreSQL's KeyAction).
type KeyAction struct {
	Action byte
	Cols   *nodes.List
}

// KeyActions is an internal helper struct for passing FK update/delete actions
// through grammar rules (matches PostgreSQL's KeyActions).
type KeyActions struct {
	UpdateAction *KeyAction
	DeleteAction *KeyAction
}

// SetQuantifier constants matching PostgreSQL's SetQuantifier enum.
const (
	SET_QUANTIFIER_DEFAULT  = int64(0)
	SET_QUANTIFIER_ALL      = int64(1)
	SET_QUANTIFIER_DISTINCT = int64(2)
)

// importQualification is an internal helper struct for passing IMPORT FOREIGN SCHEMA
// qualification type and table list through grammar rules.
// It implements the nodes.Node interface so it can be passed through %union.
type importQualification struct {
	listType  nodes.ImportForeignSchemaType
	tableList *nodes.List
}

func (n *importQualification) Tag() nodes.NodeTag { return nodes.T_Invalid }

// splitColQualList separates a list of column qualifiers (constraints and COLLATE)
// into the ColumnDef's constraints and collClause fields.
// This matches PostgreSQL's SplitColQualList function.
func applyConstraintAttrs(n *nodes.Constraint, attrs int64) {
	if attrs&int64(nodes.CAS_DEFERRABLE) != 0 {
		n.Deferrable = true
	}
	if attrs&int64(nodes.CAS_INITIALLY_DEFERRED) != 0 {
		n.Initdeferred = true
		n.Deferrable = true
	}
	if attrs&int64(nodes.CAS_NOT_VALID) != 0 {
		n.SkipValidation = true
		n.InitiallyValid = false
	}
	if attrs&int64(nodes.CAS_NO_INHERIT) != 0 {
		n.IsNoInherit = true
	}
}

func splitColQualList(qualList *nodes.List, coldef *nodes.ColumnDef) {
	if qualList == nil {
		return
	}
	var constraints []nodes.Node
	for _, item := range qualList.Items {
		if cc, ok := item.(*nodes.CollateClause); ok {
			coldef.CollClause = cc
		} else if de, ok := item.(*nodes.DefElem); ok && de.Defname == "compression" {
			if s, ok := de.Arg.(*nodes.String); ok {
				coldef.Compression = s.Str
			}
		} else if de, ok := item.(*nodes.DefElem); ok && de.Defname == "storage" {
			if s, ok := de.Arg.(*nodes.String); ok {
				coldef.StorageName = s.Str
			}
		} else if de, ok := item.(*nodes.DefElem); ok && de.Defname == "fdwoptions" {
			if l, ok := de.Arg.(*nodes.List); ok {
				coldef.Fdwoptions = l
			}
		} else {
			constraints = append(constraints, item)
		}
	}
	if len(constraints) > 0 {
		coldef.Constraints = &nodes.List{Items: constraints}
	}
}

// insertSelectOptions adds the clauses after a select_clause to its
// SelectStmt, refusing what PostgreSQL 16's insertSelectOptions refuses: a
// second ORDER BY, OFFSET, LIMIT or WITH (the select_clause was a
// parenthesized select that had its own), a limit after WITH TIES, and WITH
// TIES without ORDER BY or with SKIP LOCKED. withLoc is the WITH clause's
// first token. It reports false once the error is raised.
func insertSelectOptions(lex pgLexer, stmt *nodes.SelectStmt, sortClause *nodes.List, lockingClause *nodes.List,
	limitClause *SelectLimit, withClause *nodes.WithClause, withLoc nodes.ParseLoc) bool {
	if sortClause != nil {
		if stmt.SortClause != nil {
			grammarError(lex, codeSyntaxError, "multiple ORDER BY clauses not allowed", "", sortClauseLocation(sortClause))
			return false
		}
		stmt.SortClause = sortClause
	}
	skipLocked := hasSkipLocked(stmt.LockingClause) || hasSkipLocked(lockingClause)
	if lockingClause != nil {
		stmt.LockingClause = lockingClause
	}
	if limitClause != nil {
		if limitClause.LimitOffset != nil && stmt.LimitOffset != nil {
			grammarError(lex, codeSyntaxError, "multiple OFFSET clauses not allowed", "",
				nodes.ParseLoc(nodes.ExprLocation(limitClause.LimitOffset)))
			return false
		}
		if limitClause.LimitCount != nil && stmt.LimitCount != nil {
			grammarError(lex, codeSyntaxError, "multiple LIMIT clauses not allowed", "",
				nodes.ParseLoc(nodes.ExprLocation(limitClause.LimitCount)))
			return false
		}
		if stmt.LimitOption == nodes.LIMIT_OPTION_WITH_TIES {
			grammarError(lex, codeSyntaxError, "multiple limit options not allowed", "", -1)
			return false
		}
		if limitClause.LimitOption == nodes.LIMIT_OPTION_WITH_TIES {
			if stmt.SortClause == nil {
				grammarError(lex, codeSyntaxError, "WITH TIES cannot be specified without ORDER BY clause", "", -1)
				return false
			}
			if skipLocked {
				grammarError(lex, codeSyntaxError, "SKIP LOCKED and WITH TIES options cannot be used together", "", -1)
				return false
			}
		}
		stmt.LimitOffset = limitClause.LimitOffset
		stmt.LimitCount = limitClause.LimitCount
		stmt.LimitOption = limitClause.LimitOption
	}
	if withClause != nil {
		if stmt.WithClause != nil {
			grammarError(lex, codeSyntaxError, "multiple WITH clauses not allowed", "", withLoc)
			return false
		}
		stmt.WithClause = withClause
	}
	return true
}

// sortClauseLocation is where an ORDER BY list starts, as PostgreSQL 16
// reports it: the ExprLocation of its sort keys' expressions.
func sortClauseLocation(sortClause *nodes.List) nodes.ParseLoc {
	keys := make([]nodes.Node, len(sortClause.Items))
	for i, item := range sortClause.Items {
		keys[i] = item.(*nodes.SortBy).Node
	}
	return nodes.ParseLoc(nodes.ExprLocation(&nodes.List{Items: keys}))
}

// hasSkipLocked reports whether a locking clause list has a SKIP LOCKED item.
func hasSkipLocked(lockingClause *nodes.List) bool {
	for _, item := range lockingClause.Elems() {
		if item.(*nodes.LockingClause).WaitPolicy == int(nodes.LockWaitSkip) {
			return true
		}
	}
	return false
}

// checkWithinGroup refuses what PostgreSQL 16 refuses in a function call
// with WITHIN GROUP, at WITHIN: an ORDER BY in its arguments, DISTINCT and
// VARIADIC. It reports false once the error is raised.
func checkWithinGroup(lex pgLexer, fc *nodes.FuncCall, loc nodes.ParseLoc) bool {
	var message string
	switch {
	case fc.AggOrder != nil:
		message = "cannot use multiple ORDER BY clauses with WITHIN GROUP"
	case fc.AggDistinct:
		message = "cannot use DISTINCT with WITHIN GROUP"
	case fc.FuncVariadic:
		message = "cannot use VARIADIC with WITHIN GROUP"
	default:
		return true
	}
	grammarError(lex, codeSyntaxError, message, "", loc)
	return false
}

// relpersistenceForTemp returns the relpersistence byte based on temp flag.
// In PostgreSQL: 'p' = permanent (default), 't' = temporary
func relpersistenceForTemp(tempFlag int64) byte {
	switch tempFlag {
	case 1:
		return 't'
	case 2:
		return 'u'
	default:
		return 'p'
	}
}

// extractArgTypes extracts the type names from a list of FunctionParameter nodes.
func extractArgTypes(args *nodes.List) *nodes.List {
	if args == nil {
		return nil
	}
	result := &nodes.List{}
	for _, item := range args.Items {
		fp, ok := item.(*nodes.FunctionParameter)
		if ok {
			result.Items = append(result.Items, fp.ArgType)
		}
	}
	return result
}

// extractAggrArgTypes extracts the type names from an aggregate argument list.
// aggr_args returns a 2-element list: [args_list, Integer_marker].
// The first element is either nil (for agg(*)) or a *List of FunctionParameter nodes.
// This function extracts the ArgType from each FunctionParameter in the first element.
func extractAggrArgTypes(args *nodes.List) *nodes.List {
	if args == nil || len(args.Items) < 1 {
		return nil
	}
	// First element is the args list (may be nil for agg(*))
	argsList, ok := args.Items[0].(*nodes.List)
	if !ok || argsList == nil {
		return nil
	}
	result := &nodes.List{}
	for _, item := range argsList.Items {
		if fp, ok := item.(*nodes.FunctionParameter); ok {
			result.Items = append(result.Items, fp.ArgType)
		}
	}
	return result
}

// makeOrderedSetArgs builds the aggr_args result for ordered-set aggregates
// with both direct args and ORDER BY args.
// Returns a 2-element list: [combined_args_list, Integer{ndirectargs}].
// The combined list has the direct args followed by the ORDER BY args.
func makeOrderedSetArgs(directArgs *nodes.List, orderedArgs *nodes.List) *nodes.List {
	combined := &nodes.List{}
	ndirect := 0
	if directArgs != nil {
		combined.Items = append(combined.Items, directArgs.Items...)
		ndirect = len(directArgs.Items)
	}
	if orderedArgs != nil {
		combined.Items = append(combined.Items, orderedArgs.Items...)
	}
	return makeList2(combined, &nodes.Integer{Ival: int64(ndirect)})
}

// checkNames is PostgreSQL 16's check_func_name and check_qualified_name:
// every part of a name's indirection after its first is a name, not a
// subscript or a '*'. Otherwise it raises a syntax error at the token the
// lexer returned last and reports false.
func checkNames(lex pgLexer, indirection *nodes.List) bool {
	for _, item := range indirection.Elems() {
		if _, ok := item.(*nodes.String); !ok {
			grammarSyntaxError(lex, "syntax error")
			return false
		}
	}
	return true
}

// checkIndirection is PostgreSQL 16's check_indirection: a '*' is only the
// last element of an indirection. Otherwise it raises improper use of "*" at
// the token the lexer returned last and reports false.
func checkIndirection(lex pgLexer, indirection *nodes.List) bool {
	items := indirection.Elems()
	for i, item := range items {
		if _, ok := item.(*nodes.A_Star); ok && i < len(items)-1 {
			grammarSyntaxError(lex, "improper use of \"*\"")
			return false
		}
	}
	return true
}

// checkColumnNumber refuses an index column number outside 1..32767, as
// PostgreSQL 16's ALTER COLUMN n SET STATISTICS does, at the number (loc),
// and reports whether it is in range.
func checkColumnNumber(lex pgLexer, n int64, loc nodes.ParseLoc) bool {
	if n >= 1 && n <= math.MaxInt16 {
		return true
	}
	grammarError(lex, "22023", "column number must be in range from 1 to 32767", "", loc)
	return false
}

// checkRangeVarNames refuses a relation name of more than three parts, as
// PostgreSQL 16's makeRangeVarFromQualifiedName and makeRangeVarFromAnyName
// do, at the name's first part (loc), and reports whether it is short enough.
func checkRangeVarNames(lex pgLexer, names *nodes.List, loc nodes.ParseLoc) bool {
	items := names.Elems()
	if len(items) <= 3 {
		return true
	}
	parts := make([]string, len(items))
	for i, item := range items {
		parts[i] = item.(*nodes.String).Str
	}
	grammarError(lex, codeSyntaxError, "improper qualified name (too many dotted names): "+strings.Join(parts, "."), "", loc)
	return false
}

// intToString converts an int64 to a string representation.
func intToString(val int64) string {
	return fmt.Sprintf("%d", val)
}

// makeRangeVarFromAnyName creates a RangeVar from a qualified name list (list of String nodes).
// It handles 1-part (name), 2-part (schema.name), and 3-part (catalog.schema.name) names.
func makeRangeVarFromAnyName(names *nodes.List, location nodes.ParseLoc) *nodes.RangeVar {
	rv := &nodes.RangeVar{
		Inh:            true,
		Relpersistence: 'p',
		Location:       location,
	}
	if names == nil {
		return rv
	}
	switch len(names.Items) {
	case 1:
		rv.Relname = names.Items[0].(*nodes.String).Str
	case 2:
		rv.Schemaname = names.Items[0].(*nodes.String).Str
		rv.Relname = names.Items[1].(*nodes.String).Str
	case 3:
		rv.Catalogname = names.Items[0].(*nodes.String).Str
		rv.Schemaname = names.Items[1].(*nodes.String).Str
		rv.Relname = names.Items[2].(*nodes.String).Str
	}
	return rv
}

// pubObj is one object of a publication's list as the grammar read it, with
// its location and whether it is a bare name, which PublicationObjSpec does
// not keep.
type pubObj struct {
	spec *nodes.PublicationObjSpec
	loc  nodes.ParseLoc
	name bool
}

// preprocessPubobjList is PostgreSQL 16's preprocess_pubobj_list: the first
// object is a TABLE or TABLES IN SCHEMA, and an object without one takes the
// kind before it. A table is not CURRENT_SCHEMA; a schema is a bare name or
// CURRENT_SCHEMA, with no column list or WHERE clause. Otherwise it raises the
// error at the object and reports false.
func preprocessPubobjList(lex pgLexer, objs []pubObj) (*nodes.List, bool) {
	if objs[0].spec.Pubobjtype == nodes.PUBLICATIONOBJ_CONTINUATION {
		grammarError(lex, codeSyntaxError, "invalid publication object list", "", objs[0].loc)
		return nil, false
	}
	list := &nodes.List{Items: make([]nodes.Node, len(objs))}
	kind := objs[0].spec.Pubobjtype
	for i, o := range objs {
		list.Items[i] = o.spec
		if o.spec.Pubobjtype != nodes.PUBLICATIONOBJ_CONTINUATION {
			kind = o.spec.Pubobjtype
			continue
		}
		pt := o.spec.Pubtable
		message := ""
		switch {
		case kind == nodes.PUBLICATIONOBJ_TABLE:
			if pt == nil {
				message = "invalid table name"
			}
		case pt == nil:
		case pt.WhereClause != nil:
			message = "WHERE clause not allowed for schema"
		case pt.Columns != nil:
			message = "column specification not allowed for schema"
		case !o.name:
			message = "invalid schema name"
		}
		if message != "" {
			grammarError(lex, codeSyntaxError, message, "", o.loc)
			return nil, false
		}
	}
	return list, true
}

